import sys
import os
sys.path.append(os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))) #finds the path of other assets like the gui and logo

import tkinter as tk
from logic.spawn_logic import find_candidate #imports the find_candidate function from the main logic file
import datetime

def update_timer(): #function for formatting the current time, assigning find_candidate to variables
    now = datetime.datetime.now()
    next_spawn_time, next_boss = find_candidate(now)

    time_remaining = next_spawn_time - now #compares current time to the set spawns in the dictionary to find next boss time
    time_remaining_str = str(time_remaining).split('.')[0]  # Removes microseconds
    
    #defining labels
    current_label.config(text=f"Current Time: {now.strftime('%I:%M:%S %p')}")
    boss_label.config(text=f"Next Boss: {next_boss}") #defines next boss from candidate list
    countdown_label.config(text=f"Spawns at: {next_spawn_time.strftime('%I:%M:%S %p')} ({time_remaining_str})")

    root.after(1000, update_timer)  # Refresh every 1 second


root = tk.Tk()
root.title("Vesteria Boss Timer")
root.iconphoto(True, tk.PhotoImage(file=os.path.join(os.path.dirname(__file__), "asset", "logo.png")))
root.geometry("400x200")

current_label = tk.Label(root, font=("Verdana", 14))
boss_label = tk.Label(root, font=("Verdana", 16, "bold"))
countdown_label = tk.Label(root, font=("Verdana", 14))

current_label.pack(pady=10)
boss_label.pack(pady=5)
countdown_label.pack(pady=10)

update_timer()
root.mainloop()
